  "gt_staff_appraisals_s0b2": ["Avg score · 4.1/5", "Śr. ocena · 4,1/5", "Scor mediu · 4,1/5", "اوسط اسکور · 4.1/5", "ਔਸਤ ਸਕੋਰ · 4.1/5", "গড় স্কোর · ৪.১/৫", "متوسط الدرجات · 4.1/5", "Pontuação média · 4,1/5", "Puntuación media · 4,1/5", "Score moyen · 4,1/5", "Sgôr cyf. · 4.1/5"],
