  "gt_staff_appraisals_s1b4": ["Employee: Jess Patel · Coach", "Pracownik: Jess Patel · Trener", "Angajat: Jess Patel · Antrenor", "ملازم: Jess Patel · کوچ", "ਕਰਮਚਾਰੀ: Jess Patel · ਕੋਚ", "কর্মী: Jess Patel · কোচ", "الموظف: Jess Patel · مدرّب", "Colaborador: Jess Patel · Treinador", "Empleado: Jess Patel · Entrenador", "Employé : Jess Patel · Animateur", "Gweithiwr: Jess Patel · Hyfforddwr"],
