  "gt_staff_appraisals_s4b0": ["🌟 Kudos", "🌟 Pochwała", "🌟 Laudă", "🌟 تعریف", "🌟 ਸ਼ਲਾਘਾ", "🌟 প্রশংসা", "🌟 إشادة", "🌟 Elogio", "🌟 Elogio", "🌟 Félicitations", "🌟 Clod"],
